    const said3 = [];
    const fb3 = flash; flash = function (m) { said3.push(m); };
    try { kit.forEach(function (k) { billAction(ob.id, k); }); } finally { flash = fb3; }
    R.kitTook = { whip: ob.whip, deal: ob.upperDeal, confidence: !!ob.confidence, urgent: !!ob.urgent };
