    fresh(5150, 'shrewd');
    const P = PARTIES.map(q => q.id).filter(x => x !== playParty(S))[0];
    v16Ai(S)[P].goal = { kind:'build', ref:'machine', want:.05, from:0, since:S.turn };
    S.machine[P] = .9;
    const before = JSON.stringify(v16Ai(S)[P].goal);
    const after = v19Goal(S, P);
