        askedOneStep: Math.abs(v21Rung(S, pid, fresh1) - at) === V21_RUNG,
        legacyAsksSummit: v21Rung(S, pid, legacy) === want,
        dated: typeof fresh1.due === 'number' && fresh1.due > S.turn,
