      v22TargetSet(S, eng, r.id, 3, alien);
      const stored = v22TargetIssue(S, eng, r.id);
      return { ran:true, alien:alien, stored:stored, refused:stored !== alien,
        fellBackToTheRegions:own.indexOf(stored) >= 0 };
